            <button type="button" role="switch" class="sw" aria-checked="{{p.checked}}" aria-labelledby="{{p.lid}}" onClick="{{p.toggle}}" style="flex-shrink: 0; width: 56px; height: 44px; border: 0; padding: 0; background: none; display: flex; align-items: center; justify-content: center"><span style="position: relative; width: 50px; height: 30px; border-radius: 15px; background: {{p.track}}"><span class="knob" style="position: absolute; left: 3px; top: 3px; width: 24px; height: 24px; border-radius: 12px; background: #ffffff; box-shadow: 0 2px 4px rgba(15,23,42,.25); transform: translateX({{p.x}}px)"></span></span></button>
